class Learner:
    def __init__(self, name):
        self.name = name
        self.completed = []

    def complete(self, lesson):
        self.completed.append(lesson)

    def summary(self):
        return f'{self.name}: {len(self.completed)} completed'

mina = Learner('Mina')
leo = Learner('Leo')
mina.complete('Lists')
print(mina.summary())
print(leo.summary())
